def classify(event):
    amount = event["amount"]
    if amount < 0:
        return "refund"
    if amount >= 100:
        return "large"
    return "small"


def bucket(event):
    hour = event["hour"]
    if hour < 6:
        return "night"
    if hour < 12:
        return "morning"
    if hour < 18:
        return "afternoon"
    return "evening"


def summarize(events):
    total = 0
    counts = {}
    for event in events:
        total += event["amount"]
        label = classify(event)
        counts[label] = counts.get(label, 0) + 1
    return {"total": total, "counts": counts}
